    {"op": "map", "as": "adult", "expr": "true"},
    {"op": "rename", "from": "name", "to": "full_name"},
    {"op": "branch", "branches": [
      {"id": "branch1", "when": "adult", "steps": [
        {"op": "map", "as": "status", "expr": "\"adult\""}
      ]},
      {"when": "otherwise", "steps": [
        {"op": "map", "as": "status", "expr": "\"minor\""}
      ]}
    ]}
  ]},
  "dataset": [
    {"id": 1, "name": "Alice", "age": 25},
    {"id": 2, "name": "Bob", "age": 17}
  ]
}
EOF
python etl_pipeline.py --execute < test_comprehensive.json

